namespace sv_1b74060008e648f4b88957e4628b05cc.Services;

public record WarehouseInfo(string Id, string Name)
{
    public static readonly WarehouseInfo[] All =
    [
        new("WH-A", "Warehouse A"),
        new("WH-B", "Warehouse B"),
        new("WH-C", "Warehouse C"),
    ];

    public static WarehouseInfo Default => All[0];
}

namespace sv_1b74060008e648f4b88957e4628b05cc.Services;

/// <summary>
/// Scoped service that tracks the currently selected warehouse for one user circuit.
/// Components subscribe to <see cref="OnChange"/> to react when the selection changes.
/// </summary>
public class WarehouseState
{
    public WarehouseInfo Current { get; private set; } = WarehouseInfo.Default;

    public event Action? OnChange;

    public void SetWarehouse(WarehouseInfo warehouse)
    {
        if (Current.Id == warehouse.Id) return;
        Current = warehouse;
        OnChange?.Invoke();
    }
}

namespace sv_1b74060008e648f4b88957e4628b05cc.Services;

/// <summary>
/// Scoped service that provides low-stock alert counts and notifies all subscribers
/// when new data arrives. The polling timer lives in the dashboard page; this service
/// is the shared data store and event bus.
/// </summary>
public class InventoryAlertService
{
    private readonly Random _random = new();

    public int CurrentCount { get; private set; }

    public event Action? OnAlertCountChanged;

    /// <summary>Simulates a database query for items below minimum stock levels.</summary>
    public Task<int> GetLowStockCountAsync(string warehouseId)
    {
        return Task.FromResult(_random.Next(0, 16));
    }

    /// <summary>
    /// Called after polling completes. Stores the latest count and notifies every
    /// subscribed component (alert badges, dashboard panels, etc.).
    /// </summary>
    public void UpdateCount(int newCount)
    {
        CurrentCount = newCount;
        OnAlertCountChanged?.Invoke();
    }
}

