@using sv_1b74060008e648f4b88957e4628b05cc.Services
@inject WarehouseState WarehouseState
@inject CascadingValueSource<WarehouseInfo> WarehouseSource
@implements IDisposable

<select class="form-select form-select-sm" style="width: 200px;"
        value="@WarehouseState.Current.Id" @onchange="OnWarehouseChanged">
    @foreach (var wh in WarehouseInfo.All)
    {
        <option value="@wh.Id">@wh.Name</option>
    }
</select>

@code {
    private void OnWarehouseChanged(ChangeEventArgs e)
    {
        var id = e.Value?.ToString();
        var warehouse = WarehouseInfo.All.FirstOrDefault(w => w.Id == id);
        if (warehouse is null) return;

        WarehouseState.SetWarehouse(warehouse);
        // Push the new value to all [CascadingParameter] subscribers across render modes.
        _ = WarehouseSource.NotifyChangedAsync(warehouse);
    }

    private Action? _handler;

    protected override void OnInitialized()
    {
        _handler = () => InvokeAsync(StateHasChanged);
        WarehouseState.OnChange += _handler;
    }

    public void Dispose() => WarehouseState.OnChange -= _handler;
}

