@page "/dashboard"
@rendermode InteractiveServer
@using sv_1b74060008e648f4b88957e4628b05cc.Services
@inject WarehouseState WarehouseState
@inject InventoryAlertService AlertService
@implements IDisposable

<PageTitle>Warehouse Dashboard</PageTitle>

<h1>Warehouse Dashboard</h1>

<p>
    Currently viewing: <strong>@WarehouseState.Current.Name</strong>
    <span class="text-muted">(@WarehouseState.Current.Id)</span>
</p>

<div class="row">
    <div class="col-md-4">
        <div class="card">
            <div class="card-body text-center">
                <h5 class="card-title">Low-Stock Alerts</h5>
                <p class="display-4 @(AlertService.CurrentCount > 5 ? "text-danger" : "text-warning")">
                    @AlertService.CurrentCount
                </p>
                <p class="text-muted">items below minimum level</p>
                <small class="text-muted">Polling every 10 seconds</small>
            </div>
        </div>
    </div>
</div>

@code {
    private PeriodicTimer? _timer;
    private CancellationTokenSource? _cts;
    private Action? _warehouseHandler;
    private Action? _alertHandler;

    protected override void OnInitialized()
    {
        // React when another component changes the warehouse.
        _warehouseHandler = () => InvokeAsync(OnWarehouseChanged);
        WarehouseState.OnChange += _warehouseHandler;

        // React when alert data is refreshed (keeps this page in sync with sidebar badge).
        _alertHandler = () => InvokeAsync(StateHasChanged);
        AlertService.OnAlertCountChanged += _alertHandler;
    }

    protected override void OnAfterRender(bool firstRender)
    {
        if (firstRender)
        {
            StartPolling();
        }
    }

    private void StartPolling()
    {
        StopPolling();
        _cts = new CancellationTokenSource();
        _timer = new PeriodicTimer(TimeSpan.FromSeconds(10));
        _ = PollLoopAsync(_cts.Token);
    }

    private async Task PollLoopAsync(CancellationToken ct)
    {
        // Fetch immediately on first load, then every 10s.
        await FetchAndNotifyAsync();

        try
